C = dict(id='GL-11', title='Biometric Sensor and Security Solutions', group='Digital and Technology', level=5,
 summary='Choose, set up and test a fair, private biometric entry system for a small site, and know when not to use biometrics at all.',
 outcomes=['Explain how fingerprint, face and other biometric checks work and fail.', 'Set up a small test system with consent and a non-biometric alternative.', 'Analyse false accepts and false rejects from a trial.', 'Create a privacy notice, data plan and fallback process.', 'Evaluate whether biometrics are the right tool for the need.'],
 task='Design and trial a small access-control solution with a consent process, error measurements and a no-biometric alternative.',
 cond='Practice kit or simulator, a small group of consenting volunteers (at least 10), a spreadsheet, a mentor with security experience and a peer circle. About 10 weeks part-time.',
 std='Written consent held; error rates calculated from at least 100 attempts; template stored securely and deleted on request; alternative path works; privacy notice approved by the mentor.',
 who='Security staff, facilities managers, IT support, small-site owners, college learners.', req='Basic computer skills.',
 safety='Biometric data is highly sensitive. Use only volunteers who consent in writing. Never copy templates out of the device. Follow local law and delete data when asked.',
 mods=[
 ('What biometrics are', 'A biometric check compares a live trait with a stored template.', ['Types: fingerprint, face, iris, voice, vein pattern.', 'Enrol once, then match each time; a score decides pass or fail.', 'Templates are numbers, not photos, but still personal data.', 'Match decisions use a threshold you can move.'], 'A fingerprint reader gives a score of 0 to 100. Threshold 80: a score of 78 is rejected, 85 accepted.', 'Compare three biometric types on ease, cost and risk.', 'Complete the table with at least four points each.'),
 ('Need first, tool second', 'Ask whether a simpler lock solves the problem.', ['Define who must enter, how often and what is at risk.', 'List alternatives: key, card, code, guard.', 'Biometrics suit high-risk or high-volume places, not every door.', 'Count cost over three years, not just purchase price.'], 'A storeroom with 4 users and low-value goods: 4 key cards at 15 each cost 60, far less than a 600 reader (example prices in your currency; check your market).', 'Write a need statement and compare two tools.', 'Write a specific need statement and show the cost over 3 years.'),
 ('Privacy, consent and law', 'Trust is the product. Collect the least and say so.', ['Written, informed consent; no pressure.', 'Offer an equal non-biometric way in.', 'Store templates encrypted; never share or sell.', 'Set a retention time and a deletion route.'], 'A volunteer withdraws: their template is deleted promptly, within the time promised in the notice, and the log shows the date.', 'Write a one-page privacy notice and consent form.', 'Cover purpose, storage, deletion and alternative in the notice.'),
 ('Setting up a trial', 'Install carefully; protect the device.', ['Fit at right height and light; keep sensors clean.', 'Change default codes; limit admin rights.', 'Enrol volunteers with two samples each.', 'Keep a log of faults.'], 'Reader is fitted in direct sun; face reads fail at noon. Move it under a hood and failures drop.', 'Install or simulate the reader and enrol volunteers.', 'Enrol all volunteers and start the log.'),
 ('Measure errors', 'Accuracy is measured, not promised.', ['False accept: wrong person let in. False reject: right person refused.', 'Rates = errors divided by attempts.', 'Moving the threshold trades one error for the other.', 'Test with different people, lighting and wet or dry hands.'], 'Out of 200 right-person attempts 6 are rejected: 3%. Out of 100 impostor attempts 1 is accepted: 1%.', 'Run 100 or more attempts and compute both rates.', 'Calculate and explain both rates.'),
 ('Security of the whole system', 'Attackers go after the weak link, not the reader.', ['Spoofing: photos, copies; ask about liveness checks (tests that the trait comes from a living person).', 'Protect cables, power and the network.', 'Log entries and review them weekly.', 'Plan for lost power and for a person who cannot enrol.'], 'Power fails: door locks release for fire safety and a guard checks the log afterwards.', 'Write a threat table with five items.', 'Give each threat a control.'),
 ('Fairness and fallback', 'Systems must work for everyone.', ['Some people cannot use a trait: injury, age, work wear.', 'Check results across groups for gaps.', 'Offer card or code and keep it equally fast.', 'Handle complaints quickly.'], 'Rejection rates are 2% for office staff and 9% for cleaners with dry hands: fix with a moisture tip and an alternative.', 'Compare results across at least two groups.', 'Name the gap and propose a remedy.'),
 ('Decide, report and review', 'Say yes, no or not yet with evidence.', ['Compare error rates, cost and privacy risk with the need.', 'Write a one-page recommendation.', 'Plan a six-month review.', 'Delete trial data and record when.'], 'Recommendation: use biometrics for the server room only; cards elsewhere.', 'Write the recommendation and 90-day plan.', 'Back the decision with numbers and record the deletion.')],
 quiz=[('What is a template?', 'The stored number set made from a trait, used for matching.'), ('Define false accept.', 'The wrong person is let in.'), ('Define false reject.', 'The right person is refused.'), ('What does moving the threshold do?', 'Trades false accepts against false rejects.'), ('Why offer an alternative?', 'Some cannot use biometrics and consent must be free.'), ('What must consent be?', 'Written, informed and freely given.'), ('How do you compute an error rate?', 'Errors divided by attempts.'), ('When are biometrics not needed?', 'When a simpler, cheaper lock gives enough safety.'), ('What is spoofing?', 'Fooling the sensor with a copy.'), ('What happens to data when asked to delete?', 'It is deleted and the date recorded.')],
 rubric=[('Privacy and consent', 'Notice and written consent held', 'Deletion tested end to end'), ('Need analysis', 'Need and alternatives compared', 'Three-year cost and risk compared'), ('Measurement', 'Both error rates calculated', 'Groups compared and gap explained'), ('Security thinking', 'Five threats with controls', 'Controls tested'), ('Decision', 'Recommendation uses numbers', 'Review plan with dates')],
 jobs=[('Access-control technician', 'Installs and maintains entry systems'), ('Security systems assistant', 'Sets up and logs trials'), ('Facilities coordinator', 'Chooses locks and policies'), ('Privacy support assistant', 'Handles consent and deletion requests')],
 next='Privacy Protection Practice; DDoS and Cyber-Attack Prevention; Internet of Things.',
 local='Biometric rules are strict in many places and may need a legal basis or a regulator\'s view: check before any pilot.',
 evidence='Your evidence: need statement, consent form and notice, enrolment log, error table, threat table, fairness comparison, recommendation.',
 ladder=[('Basics of access', 'Explain how a lock, a key card, a PIN and a fingerprint each prove who you are, and what each can get wrong. Notes: look at the doors in your building and list how each is opened. Standard: a one-page list a visitor could follow.'), ('Awareness', 'Describe what a biometric is, why it cannot be changed if leaked, and when its use feels fair or unfair to the person using it. Notes: discuss two cases, a school gate and a gym, and write one rule you would set for each. Standard: your rules name consent, a choice without biometrics and who can see the data.'), ('Foundation', 'Compare a card, a PIN and a biometric reader for one need, such as a staff door, on cost, error, privacy and fallback. Notes: paper exercise with a scoring table and a written reason for the choice. Standard: scores come from stated numbers, and the fallback is described.'), ('Practitioner', 'Run a small trial of an entry solution with a simulator or a card system, count false accepts and false rejects over at least 50 attempts, and test the no-biometric route. Notes: simulator allowed; no real fingerprints or faces stored. Standard: error rates are calculated and the alternative route works.'), ('Specialist', 'Design and trial a small access-control solution with a consent process, measured errors and a no-biometric alternative, for a site of 20 people. Notes: write the notice, the retention period and the spoofing test you ran. Standard: error rates reported, consent form tested on a reader, alternative route in daily use.'), ('Advanced', 'Design access control for several sites, with a standards check, an audit trail and an independent test. Notes: add a testing lab report and a data-protection review for each site. Standard: the audit trail answers who entered, when and on whose approval, and the review is dated.'), ('Super expert', 'Set the enrolment, template and fallback standard for biometric systems and train the installers who apply it. Notes: publish consent and spoofing-test templates and review false-match and false-reject figures each year.')])

C['deep'] = dict(mods=[
 ('Believing a match score is a yes or no fact.', 'Score 78 against threshold 80 is a reject; at threshold 75 it passes. Same person, different rule.', 'What threshold did you choose and why?'),
 ('Buying a reader before stating the need.', 'A storeroom with four users is served by cards at a fraction of the cost.', 'What is your need in one sentence?'),
 ('Hiding the alternative path in small print.', 'The notice puts "ask for a card" in the first line, not the last.', 'Where is the alternative described?'),
 ('Skipping the second enrolment sample.', 'Two samples cut false rejects from 6% to 3% in the trial.', 'How many samples per person?'),
 ('Testing only with easy cases.', 'Dry-hand and wet-hand trials show rates of 2% and 11%.', 'What conditions did you test?'),
 ('Forgetting power loss.', 'Fire-safety rules often require doors to release on power loss (check your local rule); the log records every release.', 'What happens to your door in a power cut?'),
 ('Ignoring group differences.', 'Rates of 2% and 9% for two groups lead to a card option and a hand-care tip.', 'Which group had the highest rejection rate?'),
 ('Keeping trial data "just in case".', 'Templates are deleted on the planned date and the log records it.', 'When will your trial data be deleted?')],
 gloss=[('Template', 'Stored numbers made from a trait.'), ('Threshold', 'The score that decides pass or fail.'), ('False accept', 'Wrong person let in.'), ('False reject', 'Right person refused.'), ('Liveness check', 'A test that the trait comes from a live person.'), ('Enrolment', 'First recording of a person\'s trait.')],
 cases=[('The reluctant employee', 'An employee does not want a fingerprint reader.', 'What must you do?', 'Offer an equal alternative at once, with no penalty, and record the choice.'),
        ('The photo trick', 'A tester opens the face reader using a photo.', 'What does this show?', 'The system lacks a liveness check; add it or choose another method and record the weakness.')])
C['deep']['extra'] = [
 ['Learn the difference between identification (who are you?) and verification (are you who you say?).', 'Compare how often each trait changes: faces and voices change more than fingerprints.'],
 ['Ask users what would make them comfortable; their answer shapes the privacy notice.', 'Check whether a mobile phone unlock or a smart card already meets the need.'],
 ['Keep consent forms apart from the templates so one leak does not link name to data.', 'Name a person responsible for deletion requests.'],
 ['Take photos of the installation for the log, avoiding any faces.', 'Test with gloves, dust and bright sunlight, which are the usual failures.'],
 ['Make sure at least 100 attempts include different people, not one person many times.', 'Record the threshold used for each test run.'],
 ['Keep the network for the readers separate from the guest Wi-Fi.', 'Test the door release on power loss with the safety officer present.'],
 ['Review complaints and add each to the fairness log.', 'Measure the time to enter through each route; the alternative should be about as quick.'],
 ['Plan a re-test every six months, because hardware ages.', 'Write down what would make you stop using biometrics.']]
_np = [['Learn the difference between enrolment, which stores a template, and matching, which compares a new sample with it; each step has its own error sources.', 'List trait options such as fingerprint, face, iris and voice, and note for each one how easily it can be copied, how it changes with age and what hardware it needs.'], ["Write the need as a sentence with who, where and what is at stake, such as 'staff opening the storeroom, 20 people, low risk', before looking at products.", 'Compare simpler options such as cards or codes against biometrics on cost, speed, loss and misuse, and keep the simple one if it meets the need.'], ['Write a plain consent note saying what is collected, why, how long it is kept, who sees it and how a person can say no or ask for deletion.', 'Store templates rather than raw images where possible, encrypt them, and set a deletion date so data does not sit around after its purpose ends.'], ['Enrol 20 to 30 volunteers, record conditions such as light and dry or wet hands, and run at least 100 genuine attempts in total, split across your volunteers.', 'Fix the placement of the sensor at a comfortable height and test it with left and right hands and with people of different heights.'], ['Compute the false accept rate, where a wrong person is let in, and the false reject rate, where the right person is turned away, from your trial counts.', 'Move the threshold in small steps and plot both rates; the point where they meet shows the trade-off, and your choice depends on which error costs more.'], ['Map the chain from sensor to template storage to the door controller, and list one possible attack at each step, such as a fake finger or intercepted data.', 'Add a liveness check or a second factor where the risk justifies it, and keep logs of failed attempts so repeated tries trigger an alert.'], ['Compare error rates across groups such as age bands and skin tones in your trial, and flag any group whose rate is more than double the average.', 'Provide a non-biometric route, such as a card and a staff check, and make sure using it carries no penalty or delay beyond a few minutes.'], ['Summarise on one page the need, trial size, error rates, privacy steps, cost and your recommendation, and mark which numbers are measured and which are estimates.', 'Schedule a review at six months to repeat the error checks, because wear, software updates and new users change results over time.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
C['intro_add'] = ["You will explain enrolment, templates and matching, and compare common traits, so you can describe what a biometric check actually does.", "You will state a security need in one sentence and test whether cards or codes already meet it before considering biometrics.", "You will draft a consent note and a retention rule that collect the least data, protecting both users and the organisation's credibility.", "You will run a small, well-recorded trial with volunteers under varied conditions, giving you evidence rather than a supplier's claims.", "You will calculate false accept and false reject rates from trial counts and tune a threshold to the error that costs more.", "You will map the whole chain from sensor to door controller and list a likely attack at each link, adding liveness checks where justified.", "You will compare error rates across groups and design a respectful non-biometric alternative, so the system serves everyone without penalty.", "You will write a one-page recommendation separating measured from estimated figures and schedule a re-check, so your yes, no or not yet stays honest."]
